-- VibeSchool Task 1: improve one existing Mumbi2 teacher guide draft with
-- actual legacy syllabus unit trace and classroom-ready activities. This migration
-- does NOT approve, release, label verified, or alter the published source chapter.
-- On clean databases without the user-authored publication, do nothing.
do $write$
declare
 v_id uuid;
 v_body jsonb;
 v_review jsonb;
 v_count int;
begin
 select d.id into v_id
 from public.content_derivatives d
 join public.vibe_publications p on p.id=d.source_publication_id
 join public.vibe_chapters c on c.id=d.source_chapter_id
 join public.profiles pr on pr.id=p.author_id
 where pr.full_name='Mumbi2' and p.title='Vibe Agriculture Form 4'
   and c.title='Livestock Production V — Poultry'
   and d.derivative_type='teacher_notes' and d.audience='teacher' and d.status='draft'
 order by d.created_at desc limit 1;
 if v_id is null then return; end if;

 select body into v_body from public.content_derivatives where id=v_id for update;
 if v_body->>'review_basis'='VibeSchool source-grounded editorial draft; independently hosted copy of the revised Kenya secondary syllabus; not KICD endorsement or publication approval' then
   return;
 end if;
 if not (v_body ? 'source_sequence') then
   raise exception 'Teacher guide does not contain canonical source sequence';
 end if;
 v_body:=v_body||$guide${"review_basis":"VibeSchool source-grounded editorial draft; independently hosted copy of the revised Kenya secondary syllabus; not KICD endorsement or publication approval","objectives":["Identify and explain the functions of major structures in a poultry egg.","Select fertile hatching eggs using health, shape, shell integrity and cleanliness criteria.","Distinguish incubation, broodiness and post-hatch brooding, including conditions and care.","Compare free-range, fold, deep-litter and cage rearing systems using welfare, cost, management and disease-control considerations.","Relate chicken feeding requirements to age and production role.","Identify causes, effects and mitigations of stress and harmful poultry vices.","Demonstrate safe egg sorting, grading and market preparation and justify enterprise choices."],"prerequisite_knowledge":["Basic domestic livestock husbandry, animal welfare and hygiene","Differences between animal growth and reproduction","Simple farm enterprise costs, income and records"],"preparation_resources":["Clean unincubated fresh egg, labelled egg anatomy diagram, plate, handwashing supplies and appropriate disposal container","Printed comparisons of free-range, fold, deep-litter and cage systems showing welfare/cost tradeoffs","Example starter, grower, layer and broiler feed labels, or accessible printed reproductions","Sample clean egg tray and mock grading rubric; avoid handling unknown or spoiled eggs","Printed fictional Nakuru poultry-enterprise price and mortality data for a non-live case study"],"teacher_explanation":[{"heading":"Egg structure and hatching","content":"Use the existing chapter's labelled egg anatomy: shell, shell membranes, air space, albumen, chalazae, vitelline membrane, yolk and germinal disc. Clarify that fertilisation is necessary for embryonic development and shell colour alone does not indicate hatchability. Differentiate eggs selected for eating from those selected for incubation."},{"heading":"Incubation, broodiness and brooding","content":"Incubation is development before hatching; broodiness is the hen's inclination to sit and incubate; brooding is chick care after hatching. Discuss temperature, humidity, ventilation, turning and sanitation as managed conditions, but do not provide a universal machine setting without specific current equipment instructions. Demonstrate chick-distribution observations as non-invasive signs of heating problems."},{"heading":"Rearing and nutrition","content":"Contrast free range, fold systems, deep litter and cages with respect to land, cost, predation, infection management and welfare. Explain why feed and calcium needs vary between chicks, growers, laying hens and broilers; ensure clean drinking water and suitable feed quality."},{"heading":"Stress, vices and marketing","content":"Analyse crowding, inadequate feed/water, heat, rough handling, poor ventilation and disease as possible stressors. Connect management changes to reducing feather pecking, cannibalism and egg eating. Follow collection, sorting, grading, packing and hygienic handling through to market. Include Kenyan enterprise examples without asserting current market prices."}],"learner_activities":[{"name":"Diagram and function match","task":"Working in pairs, label the anatomy of an egg and explain a function for at least six parts.","evidence":"Labelled diagram plus oral justification"},{"name":"Hatching egg selection","task":"Sort a set of printed or mock egg cards by shape, shell integrity, apparent cleanliness and breeder health. Explain any uncertainty.","evidence":"Selection rubric with reasons"},{"name":"Brooding diagnosis","task":"Interpret three diagrammed chick-distribution patterns and propose a welfare-safe corrective response without handling live chicks.","evidence":"Observation → likely issue → cautious action table"},{"name":"Systems comparison","task":"Compare the four syllabus rearing systems for two fictional Kenyan farms with different land and capital constraints.","evidence":"Decision matrix with advantages, disadvantages and welfare considerations"},{"name":"Marketing case study","task":"Estimate revenue from a clearly hypothetical egg collection, account for cracked eggs and transport, then explain why revenue is not profit.","evidence":"Marked calculations and short explanation"}],"teacher_prompts":["How do incubation and brooding differ, and why can confusing them harm chicks?","Which egg features are evidence of suitability for hatching, and which cannot prove fertility?","Why might a deep-litter system suit one farm but not another?","Which changes would you prioritise if hens are feather pecking, and what evidence would you collect?","How can sorting and grading affect realised selling value without changing egg production?"],"differentiation_inclusion":["Provide a large-print/high-contrast labelled egg diagram and verbal or tactile model alternatives.","Use mixed-ability groups with defined roles (observer, recorder, explainer).","Offer sentence starters and vocabulary cards for learners needing language support.","Extend advanced learners with constrained enterprise comparisons including feed cost, loss rate and welfare.","Use images and mock materials rather than requiring access to live poultry or unsafe equipment."],"practical_safety":["Do not allow learners to operate incubators, heating elements or sharp poultry-processing equipment without trained supervision.","Use a food-safe teaching egg and clean surfaces; wash hands after handling and dispose of contents hygienically.","Do not have learners handle diseased birds or perform invasive livestock procedures.","Follow school safety rules and current veterinary or agricultural extension guidance."],"has_practical":true,"outcome_coverage":{"source_type":"legacy_secondary_syllabus_independent_host_copy","target":"Agriculture Form Four 27.1.0 objectives (a) through (o), 27.2.0","source_locator":"printed pages 114–115","mapping_status":"editorial_candidate_not_officially_promoted","topics":["parts of egg","incubation and sources of chicks","natural and artificial brooding","systems and feeding","stress and vices","egg and meat marketing","poultry economic value"],"caution":"Existing chapter-linked outcomes are creator-claimed; no official source-type outcome rows or authoritative chapter verification has been established."},"answer_guidance":{"incubation_vs_brooding":"Incubation supports embryo development before hatch; brooding provides warmth, safety, water and feed for chicks after hatch.","selection_eggs":"Healthy breeding origin, intact clean shells, normal shape, suitable size and appropriate handling; shell colour alone is not proof of fertility.","stress_control":"Correct overcrowding, ventilation and heat, feed and water access, lighting and injuries while observing flock welfare."},"closure_reflection":{"exit_ticket":"Give one evidence-based rule for hatching egg selection, one sign of brooder mismanagement, and a welfare-safe correction.","next_lesson":"Use the enterprise decision matrix to introduce cattle management or compare animal enterprise management decisions.","teacher_record":"Record the objective learners missed and their evidence; do not infer mastery from participation alone."},"citations":[{"type":"secondary_syllabus","url":"https://kcserevision.com/wp-content/uploads/2025/05/SYLLABUS-ORIGINAL-FOR-MATH-PHYSICS-CHEMISTRY-BIOLOGY-AGRICULTURE-HOME-SCIENCE.pdf","description":"Revised secondary education syllabus volume two, Agriculture Form Four 27.1.0–27.2.8, printed pp. 114–115. Independently hosted copy; publisher provenance to be confirmed."},{"type":"existing_vibeschool_chapter","chapter_title":"Livestock Production V — Poultry","description":"Existing chapter and source-block IDs in VibeSchool, used for explanations and non-live student activities."}],"release_note":"Prepared for independent accuracy, source provenance, originality, teacher quality and authorised editorial approval. Do not promote to VibeSchool Verified or mark approved from this authored draft alone."}$guide$::jsonb;
 v_review:=public.content_worker_teacher_guide_self_review(v_body,'{}'::jsonb);
 if coalesce((v_review->>'passed')::boolean,false) is not true
    or jsonb_array_length(v_review->'blockers')<>0 then
   raise exception 'Teacher guide draft structural review not ready: %',v_review;
 end if;

 update public.content_derivatives
 set body=v_body,
     quality=coalesce(quality,'{}'::jsonb)||jsonb_build_object(
       'professional_self_review',v_review,
       'draft_classroom_structure_completed',true,
       'source_hosted_independently',true,
       'quality_candidate',false,
       'requires_editorial_approval',true,
       'evidence_grade','editorial_source_comparison_only',
       'content_review_status','pending_independent_accuracy_rights_and_originality_review'),
     updated_at=clock_timestamp()
 where id=v_id and status='draft';
 get diagnostics v_count=row_count;
 if v_count<>1 then raise exception 'One and only one guide must be updated'; end if;
end $write$;
